        cand = sorted(candidates)
        res, path = [], []

        def dfs(start, remain):
            if remain == 0:
                res.append(path[:])
                return
            for j in range(start, len(cand)):
                if j > start and cand[j] == cand[j - 1]:
                    continue               # same value already tried at this depth
                if cand[j] > remain:
                    break
                path.append(cand[j])
                dfs(j + 1, remain - cand[j])
                path.pop()

        dfs(0, target)
        return res

